package com.example.productapp.repository;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import java.util.Optional;

@Repository
public interface ProductRepository extends JpaRepository<Product, Long> {

    Optional<Product> findBySku(String sku);

    default boolean existsBySku(String sku) {
        return findBySku(sku).isPresent();
    }
}
```

### 5. Entidad de Producto (`src/main/java/com/example/productapp/entity/Product.java`)

```java
package com.example.productapp.entity;

import jakarta.persistence.*;

@Entity
@Table(name = "products")
public class Product {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String name;

    @Column(unique = true, nullable = false)
    private String sku;

    public Product() {}

    public Product(String name, String sku) {
        this.name = name;
        this.sku = sku;
    }

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    public String getSku() { return sku; }
    public void setSku(String sku) { this.sku = sku; }
}
```

### 6. Pruebas Unitarias (`src/test/java/com/example/productapp/ProductServiceTest.java`)

Estas pruebas utilizan `@ExtendWith(TestcontainersExtension.class)` para asegurar que el contenedor esté disponible durante la ejecución de las pruebas. Verifican la creación exitosa y fallida debido a la restricción de SKU único.

```java
package com.example.productapp;

import com.example.productapp.entity.Product;
import com.example.productapp.repository.ProductRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest
@Transactional
class ProductServiceTest {

    @Autowired
    private ProductRepository productRepository;

    @BeforeEach
    void setUp() {
        // Limpiar tablas antes de cada prueba para garantizar aislamiento
        productRepository.deleteAll();
    }

    @Test
    @DisplayName("Debería crear un nuevo producto exitosamente")
    void shouldCreateNewProductSuccessfully() {
        Product product = new Product("Nuevo Producto", "SKU-NUEVO-999");
        product.setName(product.getName());
        product.setSku(product.getSku());

        productRepository.save(product);

        Optional<Product> found = productRepository.findById(product.getId());
        assertThat(found).isPresent();
        assertThat(found.get().getSku()).isEqualTo("SKU-NUEVO-999");
    }

    @Test
    @DisplayName("No debería permitir crear un producto con código duplicado (ON CONFLICT)")
    void shouldNotAllowDuplicateSku() {
        // Intentar insertar un SKU que ya existe
        Product duplicateProduct = new Product("Duplicado", "SKU-A-001");
        duplicateProduct.setName(duplicateProduct.getName());
        duplicateProduct.setSku(duplicateProduct.getSku());

        // saveAndFlush lanza excepción si hay conflicto en la transacción
        // Si usamos @Transactional, la operación fallará o se revertirá según la estrategia
        // Para probar el comportamiento específico de la DB, usaremos try-catch o validación directa

        boolean created = productRepository.existsBySku("SKU-A-001");
        assertThat(created).isTrue(); // El producto original sigue existiendo

        // Intentar guardar el duplicado dentro de la misma transacción
        try {
            productRepository.save(duplicateProduct);
            // Si llegamos aquí sin excepción, significa que la implementación maneja el conflicto silenciosamente
            // O bien, Spring Data JPA lanzará una JpaPersistenceException
            // La prueba pasa si detectamos que NO se creó como entidad nueva o se lanzó error
            // Dado que usamos @Transactional, si falla la DB, la transacción se rollbackea.

            // Verificación alternativa: intentar recuperar el ID asignado (si hubo éxito parcial)
            // Pero lo más robusto es validar que el conteo total no aumente tras el intento fallido
            long countBefore = productRepository.count();
            productRepository.save(duplicateProduct); // Esto lanzará JpaPersistenceException
            // La siguiente línea nunca se ejecutará si la excepción se propaga correctamente

            // Para evitar excepciones en el flujo normal de prueba y demostrar el fallo:
            // Capturamos la excepción esperada
            assertThrows(JpaPersistenceException.class, () -> {
                productRepository.save(duplicateProduct);
            });

        } catch (JpaPersistenceException e) {
            // Esperado: Error de integridad referencial por clave única
            assertThat(e.getMessage()).contains("duplicate key value violates unique constraint");
        }
    }

