            var query = driver.FindElement(By.Name("q"));
            query.SendKeys("Cheese");
            query.Submit();

            // Esperar a que cargue Google
            await Task.Delay(3000); 

            Assert.IsTrue(driver.Title.Contains("Google"), $"Title expected to contain 'Google', got '{driver.Title}'");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error en prueba {x}: {ex.Message}");
            throw; // O manejar según estrategia de negocio
        }
        finally
        {
            driver.Quit();
        }
    }

    private static IWebDriver Driver { get; set; }

    private async Task WaitForHubAvailability()
    {
        var maxAttempts = 30;
        var attempt = 0;

        while (attempt < maxAttempts)
        {
            try
            {
                // Intentar establecer sesión temporalmente para verificar salud
                var tempCaps = new DesiredCapabilities();
                tempCaps.SetCapability("browserName", "chrome");

                using (var client = new HttpClient())
                {
                    // Verificar endpoint /status o intentar session creation breve
                    var response = await client.GetAsync($"{Url}/wd/hub/status");

                    if (response.IsSuccessStatusCode || response.StatusCode == System.Net.HttpStatusCode.OK)
                    {
                        break; // Hub listo
                    }
                }
            }
            catch (HttpRequestException)
            {
                // Hub no responde, esperar y repetir
                await Task.Delay(RetryDelaySeconds * 1000);
                attempt++;
            }
        }
    }

    // Método auxiliar para manejo de errores en caso de fallo inicial
    private async Task<T> ExecuteWithRetry<T>(Func<Task<T>> operation, int attempts = 3)
    {
        for (int i = 0; i < attempts; i++)
        {
            try
            {
                return await operation();
            }
            catch (ConnectionClosedException)
            {
                if (i == attempts - 1) throw;
                await Task.Delay(TimeSpan.FromSeconds(2));
            }
        }
        throw new InvalidOperationException("Failed after multiple retries.");
    }
}
```

