// Helper function to get instance metadata
function getInstanceMetadata(): Record<string, string> {
  const metadata: Record<string, string> = {
    POD_NAME: process.env.POD_NAME || 'unknown',
    POD_NAMESPACE: process.env.POD_NAMESPACE || 'unknown',
    NODE_NAME: process.env.NODE_NAME || 'unknown',
    HOSTNAME: process.env.HOSTNAME || 'unknown',
    IP_ADDRESS: process.env.IP_ADDRESS || 'unknown',
    CONTAINER_ID: process.env.CONTAINER_ID || 'unknown',
  };

  // Fallback to process properties if env vars are not set (K8s usually sets them)
  if (!metadata.POD_NAME) metadata.POD_NAME = process.env.POD_NAME;
  if (!metadata.NODE_NAME) metadata.NODE_NAME = process.env.NODE_NAME;

