        // Sin embargo, el factory suele esperar objetos construidos.

        // La forma correcta en v6 es instanciar manualmente el SharedIndexInformerImpl 
        // o usar el método específico si existe, pero lo más robusto es:

        return client.informers().forResource(MyResource.class).watch(watchBuilder).index(indexerBuilder).build();
    }

    // Método auxiliar para añadir el event handler
    public void addEventHandler(MyEventHandler handler) {
