records.prediction:
To create a ConfigMap and a Secret using the Go Kubernetes API, you must use the `k8s.io/client-go` library. Below is a complete, minimal, and valid example demonstrating how to initialize the client, create a ConfigMap, and create a Secret (both in-place and from a file).

### Prerequisites
Ensure you have the necessary dependencies in your `go.mod`:
```bash
go get k8s.io/client-go
go get k8s.io/apimachinery/pkg/apis/meta/v1
```

### Go Code Example

This example assumes you have a running Kubernetes cluster and the kubeconfig is available at `~/.kube/config`.

```go
package main

import (
	"context"
	"fmt"
	"os"

	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	"k8s.io/client-go/tools/clientcmd"
	"k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/api/resource"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	v1 "k8s.io/client-go/kubernetes/typed/core/v1"
)

func main() {
	// 1. Load kubeconfig
	config, err := clientcmd.BuildConfigFromFlags("", "~/.kube/config")
	if err != nil {
		fmt.Println("Error loading kubeconfig:", err)
		os.Exit(1)
	}

	// 2. Create Kubernetes Clientset
	clientset, err := kubernetes.NewForConfig(config)
	if err != nil {
		fmt.Println("Error creating clientset:", err)
		os.Exit(1)
	}

	// 3. Create ConfigMap
	configMap := createConfigMap(clientset)
	fmt.Println("ConfigMap created:", configMap.Name)

	// 4. Create Secret
	secret := createSecret(clientset)
	fmt.Println("Secret created:", secret.Name)
}

func createConfigMap(clientset *kubernetes.Clientset) *v1.ConfigMap {
	configMap := &v1.ConfigMap{
		ObjectMeta: metav1.ObjectMeta{
			Name:      "my-app-config",
			Namespace: "default",
		},
		Data: map[string]string{
			"app.name":     "my-application",
			"environment":  "production",
			"debug.mode":   "false",
		},
	}

	_, err := clientset.CoreV1().ConfigMaps("default").Create(context.TODO(), configMap, metav1.CreateOptions{})
	if err != nil {
		if errors.IsAlreadyExists(err) {
			fmt.Println("ConfigMap already exists, updating...")
			_, err = clientset.CoreV1().ConfigMaps("default").Update(context.TODO(), configMap, metav1.UpdateOptions{})
		} else {
			fmt.Println("Error creating ConfigMap:", err)
			os.Exit(1)
		}
	}
	return configMap
}

func createSecret(clientset *kubernetes.Clientset) *v1.Secret {
	// Option A: Create from a map (StringData for string secrets)
	secret := &v1.Secret{
		ObjectMeta: metav1.ObjectMeta{
			Name:      "my-app-secret",
			Namespace: "default",
		},
		Type: v1.SecretTypeOpaque, // Use v1.SecretTypeOpaque for string data
		Data: map[string][]byte{
			"api-key": []byte("super-secret-api-key-123"),
			"token":   []byte("jwt-token-here"),
		},
	}

	_, err := clientset.CoreV1().Secrets("default").Create(context.TODO(), secret, metav1.CreateOptions{})
	if err != nil {
		if errors.IsAlreadyExists(err) {
			fmt.Println("Secret already exists, updating...")
			_, err = clientset.CoreV1().Secrets("default").Update(context.TODO(), secret, metav1.UpdateOptions{})
		} else {
			fmt.Println("Error creating Secret:", err)
			os.Exit(1)
		}
	}
	return secret
}
```

### Key Technical Details

1.  **Client Initialization**: Uses `clientcmd.BuildConfigFromFlags` to read the standard `~/.kube/config`.
2.  **ConfigMap**:
    *   Uses `Data: map[string]string` for key-value pairs.
    *   Handles `IsAlreadyExists` error to allow updates if the resource is pre-existing.
3.  **Secret**:
    *   **Crucial**: Kubernetes Secrets are stored as base64-encoded bytes. You must use `map[string][]byte` and set the `Type` to `v1.SecretTypeOpaque` (or `kubernetes.io/tls`, etc.).
    *   **Encoding**: The Go `[]byte` slice is automatically base64-encoded by the Kubernetes API server when stored.
    *   **Decoding**: When retrieved, you must decode the bytes back to strings using `base64.StdEncoding`.
4.  **Context**: Uses `context.TODO()` which is standard for simple examples; in production, use a specific `context.Context` with a timeout.

