    // Configura el kubeconfig temporalmente (puede ser un archivo o in-memory)
    // Si no tienes kubeconfig, usa clientcmd.NewDefaultClientConfigLoadingRules()
    // apuntando a un archivo temporal o usa credenciales de servicio.

    // Ejemplo: Leer kubeconfig de un archivo temporal o usar credentials
    kubeconfig := clientcmd.NewDefaultClientConfigLoadingRules().Get()
    config, err := clientcmd.NewDefaultClientConfigFromBytes(kubeconfig).ClientConfig()
    if err != nil {
        fmt.Println("Error config:", err)
        return
    }

    clientset, err := kubernetes.NewForConfig(config)
    if err != nil {
