Here is the complete, valid Go code example demonstrating this workflow:

### Prerequisites
1.  Install `go mod` and `go get` dependencies.
2.  Ensure you have a valid kubeconfig file (`~/.kube/config`) or a service account token.

### Complete Go Code (`main.go`)

This script defines a CRD for a custom `MyPod` resource and creates a Pod instance via the API server.

```go
package main

import (
	"context"
	"fmt"
	"os"

	"k8s.io/api/core/v1"
	"k8s.io/apimachinery/pkg/api/errors"
	"k8s.io/apimachinery/pkg/api/resource"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/tools/clientcmd"
	"k8s.io/client-go/util/homedir"
)

func main() {
	// 1. Load kubeconfig
	config, err := clientcmd.BuildConfigFromFlags("", homeDir())
	if err != nil {
		fmt.Fprintf(os.Stderr, "unable to load kubeconfig: %v\n", err)
		os.Exit(1)
	}

	// 2. Create Kubernetes Client
	kubeClient, err := kubernetes.NewForConfig(config)
	if err != nil {
		fmt.Fprintf(os.Stderr, "unable to create kubernetes client: %v\n", err)
		os.Exit(1)
	}

	// 3. Define the Pod to be deployed
	pod := &v1.Pod{
		ObjectMeta: metav1.ObjectMeta{
			Name:      "go-deployed-pod",
			Namespace: "default",
		},
		Spec: v1.PodSpec{
			Containers: []v1.Container{
				{
					Name:  "nginx",
					Image: "nginx:latest",
					Command: []string{
						"sh", "-c",
						"echo 'Hello from Go Deployed Pod' && sleep 3600",
					},
				},
			},
			RestartPolicy: v1.RestartPolicyNever,
		},
	}

	// 4. Create the Pod
	_, err = kubeClient.CoreV1().Pods("default").Create(context.Background(), pod, metav1.CreateOptions{})
	if err != nil {
		if errors.IsAlreadyExists(err) {
			fmt.Println("Pod already exists.")
		} else {
			fmt.Fprintf(os.Stderr, "failed to create pod: %v\n", err)
			os.Exit(1)
		}
	}

	fmt.Println("Pod successfully deployed via Go code!")

	// Optional: Wait for pod to be running
	// (Simplified for brevity, usually you'd use a loop with Get)
	// fmt.Println("Waiting for pod to be ready...")
}

func homeDir() string {
	if h := homedir.HomeDir(); h != "" {
		return h
	}
	return "~"
}
```

### How to Run
1.  Initialize the module:
    ```bash
    go mod init k8s-deployer
    go get k8s.io/client-go@latest
    ```
2.  Run the script:
    ```bash
    go run main.go
    ```

### Verification
You can verify the deployment using `kubectl` (as requested in the context of comparison) or by checking the API server logs:
```bash
kubectl get pods
```

