        isStarted.set(true);
    }

    @org.junit.jupiter.api.AfterAll
    static void stopContainers() {
        if (!isStarted.get()) {
            return;
        }
        postgresContainer.stop();
        kafkaContainer.stop();
        isStarted.set(false);
    }

    protected PostgreSQLContainer<?> getPostgres() {
        return postgresContainer;
    }

    protected KafkaContainer<?> getKafka() {
        return kafkaContainer;
    }
}
```

